// ------------------------------------------------------- Iconos de tema
// The eleven concept glyphs the illustrator delivered for "Explora por
// tema" (ronda 2), inlined as React SVG rather than referenced as files.
// Two hard rules from the handoff, both learned the expensive way:
//
//   NEVER <img>        it kills the theme — the glyph can't inherit the
//                      chip's color through hover/selected/dark.
//   NEVER mask-image   tested: the SVG renders UNCLIPPED behind the mask
//                      and the cell fills with a solid square.
//
// So: one <path>, fill="currentColor", aria-hidden. The chip owns the
// color; the glyph only owns its shape.
//
// ---------------------------------------------------------- The viewBox
// The delivered art is NOT normalized inside its 24x24 viewBox. Measured
// with getBBox() across all eleven: horizontally they agree (every glyph
// opens at x≈1.6 and runs ≈20.79 wide), vertically they do not — `f1`
// occupies y 8.87 for 6.26 units of height while `audiencias` occupies
// y 1.60 for 20.80. Rendered at one nominal size the car weighs less than
// a third of a ball.
//
// The source fix is re-exporting the eleven cropped to their own ink
// (blocked on the illustrator, see docs/TODO.md). Until then each glyph
// carries its measured viewBox here and the component sizes it:
//
//   height = --tema-icon-size x k
//   width  = --tema-icon-size x w,  w = k x min(vbW/vbH, 2.1)
//
// `k` is an optical-height correction for the two glyphs whose stroke
// mass lies about their size (`f1` and `audiencias`); the other nine sit
// at 1. The 2.1:1 width cap is what stops `f1`'s true 3.32:1 from
// rendering a 41px sliver next to a 15px ball — inside the capped box the
// default preserveAspectRatio letterboxes it, which is the intended
// trade: shorter than nominal, but still twice the ink it had at 24x24.
//
// --tema-icon-size is set in CSS (styles/sections.css), not here, so the
// desktop/mobile step (15px -> 21px) stays a breakpoint concern.

import type { CSSProperties } from 'react';

export type TemaIconName =
  | 'futbol'
  | 'basquetbol'
  | 'beisbol'
  | 'futbol-americano'
  | 'f1'
  | 'derechos-tv'
  | 'patrocinios'
  | 'finanzas'
  | 'inversion'
  | 'venues'
  | 'audiencias';

type Glyph = {
  /** Measured ink bounds, 0.4 of air, rounded to two decimals. */
  viewBox: string;
  /** Height factor against the nominal size. */
  k: number;
  /** Width factor: k x min(vbW/vbH, 2.1). */
  w: number;
  d: string;
};

