// -------------------------------------------------- Chip label -> glyph
// Twelve topics, eleven glyphs. Fútbol and Liga MX SHARE `futbol` on
// purpose — do not invent a substitute for Liga MX.
//
// F1 is deliberately absent. `f1.svg` carries the Formula 1 wordmark as a
// knockout in the sidepod: a registered mark of Formula One Licensing BV,
// and the only glyph delivered as a filled silhouette while the other ten
// are line work. Both problems need the original illustrator, not code.
// Until it is redrawn we apply the publisher's own rule — a topic with no
// glyph in this table renders with NO icon, never a generic placeholder.
// The `f1` entry stays in GLYPHS above so re-enabling it is one line here.
// See docs/TODO.md.
export const TEMA_ICON_BY_TOPIC: Record<string, TemaIconName> = {
  'Fútbol': 'futbol',
  'Liga MX': 'futbol',
  'NFL': 'futbol-americano',
  'NBA': 'basquetbol',
  'Béisbol': 'beisbol',
  'Derechos de TV': 'derechos-tv',
  'Patrocinios': 'patrocinios',
  'Finanzas': 'finanzas',
  'Inversión': 'inversion',
  'Venues': 'venues',
  'Audiencias': 'audiencias',
};

export function TemaIcon({ name }: { name: TemaIconName | undefined }) {
  const glyph = name ? GLYPHS[name] : undefined;
  // No glyph is a valid outcome, not a hole to fill with a generic shape.
  if (!glyph) return null;

  const style: CSSProperties = {
    height: `calc(var(--tema-icon-size, 15px) * ${glyph.k})`,
    width: `calc(var(--tema-icon-size, 15px) * ${glyph.w})`,
  };

  return (
    <svg
      className="tema-icon"
      viewBox={glyph.viewBox}
      style={style}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
    >
      <path fillRule="evenodd" clipRule="evenodd" d={glyph.d} />
    </svg>
  );
}
